import React, { useState, useEffect } from 'react';
import { Download, Mail, Github, Linkedin, Code, Database, Cloud, ChevronDown, Sparkles } from 'lucide-react';

const Hero = () => {
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [currentRole, setCurrentRole] = useState(0);

  const roles = [
    { title: "Full-Stack Developer", icon: <Code size={24} />, color: "from-blue-500 to-purple-600" },
    { title: "Data Analyst", icon: <Database size={24} />, color: "from-green-500 to-teal-600" },
    { title: "IT Officer", icon: <Cloud size={24} />, color: "from-orange-500 to-red-600" }
  ];

  useEffect(() => {
    const handleMouseMove = (e) => {
      setMousePosition({ x: e.clientX, y: e.clientY });
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentRole((prev) => (prev + 1) % roles.length);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  return (
    <section className="min-h-screen relative overflow-hidden bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      {/* Dynamic Background */}
      <div className="absolute inset-0">
        {/* Animated mesh gradient */}
        <div className="absolute inset-0 bg-gradient-to-br from-blue-600/20 via-purple-600/20 to-teal-600/20"></div>

        {/* Interactive cursor follower */}
        <div 
          className="absolute w-96 h-96 bg-gradient-to-r from-blue-400/30 to-purple-400/30 rounded-full blur-3xl transition-all duration-1000 ease-out"
          style={{
            left: mousePosition.x - 192,
            top: mousePosition.y - 192,
          }}
        ></div>

        {/* Floating geometric shapes */}
        <div className="absolute top-20 left-20 w-32 h-32 border border-blue-400/30 rounded-3xl rotate-45 animate-float"></div>
        <div className="absolute top-40 right-32 w-24 h-24 bg-gradient-to-r from-purple-500/20 to-pink-500/20 rounded-full animate-float" style={{animationDelay: '1s'}}></div>
        <div className="absolute bottom-32 left-32 w-20 h-20 border-2 border-teal-400/40 rotate-12 animate-float" style={{animationDelay: '2s'}}></div>
        <div className="absolute bottom-20 right-20 w-16 h-16 bg-gradient-to-r from-orange-500/30 to-red-500/30 rounded-lg rotate-45 animate-float" style={{animationDelay: '3s'}}></div>

        {/* Grid pattern overlay */}
        <div className="absolute inset-0 opacity-40">
          <div className="absolute inset-0" style={{
